/* The order designs are shown in, and their display numbers (01 = first). The list above is the default, best first.
   A viewer's own arrangement (gallery: Arrange) is kept in this browser, and ?order=05,12,... in a link sets it.
   Each design keeps its fixed id (its folder number) for links, shortlists and font choices; c.no is its place. */
(function () {
  var L = window.TP_CONCEPTS, o = null;
  window.TP_DEFAULT_ORDER = L.map(function (c) { return c.id; });
  try {
    var q = new URLSearchParams(location.search).get('order');
    if (q) { o = q.split(','); localStorage.setItem('tp-order', JSON.stringify(o)); }
    else o = JSON.parse(localStorage.getItem('tp-order') || 'null');
  } catch (e) {}
  if (o && o.length) {
    var seen = {}, r = [];
    o.forEach(function (id) { var c = L.filter(function (x) { return x.id === id; })[0]; if (c && !seen[id]) { seen[id] = 1; r.push(c); } });
    L.forEach(function (c) { if (!seen[c.id]) r.push(c); });
    window.TP_CONCEPTS = L = r;
  }
  L.forEach(function (c, i) { c.no = String(i + 1).padStart(2, '0'); });
})();

/* Font styles: three pairings per concept (option 1 is the design's own). Picked from the switcher's Aa menu and
   remembered per concept; ?font=2 picks one for a link or a preview frame. Each element that uses the design's display
   or body font is tagged once (with the override switched off), then one stylesheet swaps the families. */
(function () {
  var slug = document.documentElement.getAttribute('data-concept');
  var c = (window.TP_CONCEPTS || []).find(function (x) { return x.slug === slug; });
  if (!c || !c.fonts) return;
  var F = c.fonts, KEY = 'tp-font-' + c.id;
  var norm = function (s) { return (s || '').split(',')[0].replace(/["']/g, '').trim().toLowerCase(); };
  var D0 = norm(F[0][1]), B0 = norm(F[0][2]), same = D0 === B0;
  var SERIF = /bodoni|playfair|fraunces|serif|garamond|newsreader|caslon/i;
  var style = document.createElement('style'), links = {}, cur = 0;
  function tag() {
    style.disabled = true;
    var all = document.body.getElementsByTagName('*');
    for (var k = 0; k < all.length; k++) {
      var e = all[k];
      if (e.hasAttribute('data-tpf') || e.hasAttribute('data-concept-switcher')) continue;
      var cs = getComputedStyle(e), f = norm(cs.fontFamily);
      if (f === D0 && (!same || /^H[1-3]$/.test(e.tagName) || parseFloat(cs.fontSize) >= 28)) e.setAttribute('data-tpf', 'd');
      else if (f === B0) e.setAttribute('data-tpf', 'b');
    }
    style.disabled = false;
  }
  function fam(n) { return '"' + n + '",' + (SERIF.test(n) ? 'Georgia,serif' : 'system-ui,sans-serif'); }
  function load(q) {
    if (!q || links[q]) return;
    var l = document.createElement('link');
    l.rel = 'stylesheet'; l.href = 'https://fonts.googleapis.com/css2?family=' + q + '&display=swap';
    document.head.appendChild(l); links[q] = l;
  }
  function refresh() {
    (document.fonts ? document.fonts.ready : Promise.resolve()).then(function () {
      setTimeout(function () {
        dispatchEvent(new Event('resize'));
        if (window.ScrollTrigger) ScrollTrigger.refresh();
      }, 60);
    });
  }
  function apply(k) {
    k = Math.max(0, Math.min(F.length - 1, k | 0));
    var was = cur; cur = k;
    if (!style.parentNode) document.head.appendChild(style);
    if (k === 0) style.textContent = '';
    else {
      tag(); load(F[k][3]);
      style.textContent = '[data-tpf=d]{font-family:' + fam(F[k][1]) + '!important;font-synthesis-weight:none}' +
        '[data-tpf=b]{font-family:' + fam(F[k][2]) + '!important}';
    }
    document.documentElement.setAttribute('data-font', k + 1);
    if (k !== was) refresh();
  }
  var q = +(new URLSearchParams(location.search).get('font') || 0), saved = 0;
  try { saved = +(localStorage.getItem(KEY) || 1); } catch (e) {}
  var start = (q >= 1 && q <= F.length ? q : saved || 1) - 1;
  if (start) { apply(start); addEventListener('load', function () { tag(); setTimeout(tag, 2000); }); }
  window.TP_FONT = {
    list: F, current: function () { return cur; },
    set: function (k) { apply(k); try { localStorage.setItem(KEY, String(k + 1)); } catch (e) {} },
    preload: function () { F.forEach(function (f) { load(f[3]); }); }
  };
})();

/* Button style picker: reshapes the main buttons (Book a chat, Call, the phone quick bar) on a concept page.
   Colours stay the design's own; only the shape changes. Kept per design in this browser; ?btn=N sets it. */
(function () {
  var slug = document.documentElement.getAttribute('data-concept');
  var c = (window.TP_CONCEPTS || []).find(function (x) { return x.slug === slug; });
  if (!c) return;
  var KEY = 'tp-btn-' + c.id, cur = 0, style = document.createElement('style');
  var B = ['.btn', '.bt', '.qbar a', '.qbar button', '.qb a', '.qb button'].join(',');
  var LIST = [['Original', 'As designed'], ['Pill', 'Fully rounded'], ['Rounded', 'Soft corners'], ['Square', 'Crisp corners'], ['Pill with arrow', 'Fully rounded, with an arrow after the label'], ['iOS style', 'Soft corners, system font, flat'], ['One UI style', 'Bold full pill, roomy and flat'], ['Material style', 'Compact pill with a light lift']];
  var CSS = {
    1: ':is(' + B + '){border-radius:999px!important}',
    2: ':is(' + B + '){border-radius:12px!important}',
    3: ':is(' + B + '){border-radius:3px!important}',
    4: ':is(' + B + '){border-radius:999px!important}' +
       '.tpb-ar{display:inline-block;margin-left:.5em;font-weight:600;line-height:1;transition:transform .5s cubic-bezier(.22,1,.36,1)}' +
       ':is(.btn,.bt):hover .tpb-ar{transform:translateX(3px)}',
    5: ':is(' + B + '){border-radius:14px!important;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Helvetica Neue",system-ui,sans-serif!important;font-weight:600!important;letter-spacing:-.01em!important;text-transform:none!important;box-shadow:none!important}' +
       ':is(.btn,.bt){min-height:50px!important;padding-inline:22px!important}',
    6: ':is(' + B + '){border-radius:999px!important;font-family:"SamsungOne","Samsung Sans",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif!important;font-weight:700!important;letter-spacing:0!important;text-transform:none!important;box-shadow:none!important}' +
       ':is(.btn,.bt){min-height:52px!important;padding-inline:30px!important}',
    7: ':is(' + B + '){border-radius:999px!important;font-family:Roboto,system-ui,-apple-system,"Segoe UI",sans-serif!important;font-weight:500!important;letter-spacing:.01em!important;text-transform:none!important}' +
       ':is(.btn,.bt){min-height:44px!important;padding-inline:24px!important;font-size:15px!important;box-shadow:0 1px 2px rgba(0,0,0,.3),0 1px 3px 1px rgba(0,0,0,.15)!important;transition:box-shadow .3s ease!important}' +
       ':is(.btn,.bt):hover{box-shadow:0 1px 2px rgba(0,0,0,.3),0 2px 6px 2px rgba(0,0,0,.15)!important}'
  };
  /* the arrow is a real element inside each button (designs already use ::before and ::after for their own effects) */
  function arrows(on) {
    document.querySelectorAll('.tpb-ar').forEach(function (x) { x.remove(); });
    if (!on) return;
    document.querySelectorAll('.btn,.bt').forEach(function (b) {
      if (b.closest('[aria-hidden="true"]') || b.textContent.indexOf('\u2192') >= 0) return;
      var t = b.querySelector('.lbl') || b, a = document.createElement('span');
      a.className = 'tpb-ar'; a.setAttribute('aria-hidden', 'true'); a.textContent = '\u2192'; t.appendChild(a);
    });
  }
  function apply(k) {
    k = Math.max(0, Math.min(LIST.length - 1, k | 0)); cur = k;
    if (!style.parentNode) document.head.appendChild(style);
    style.textContent = CSS[k] || '';
    document.documentElement.setAttribute('data-btn', k + 1);
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { arrows(cur === 4); }); else arrows(k === 4);
  }
  var q = +(new URLSearchParams(location.search).get('btn') || 0), saved = 0;
  try { saved = +(localStorage.getItem(KEY) || 1); } catch (e) {}
  apply((q >= 1 && q <= LIST.length ? q : saved || 1) - 1);
  window.TP_BTN = {
    list: LIST, current: function () { return cur; },
    set: function (k) { apply(k); try { localStorage.setItem(KEY, String(k + 1)); } catch (e) {} }
  };
})();

